CREATE TABLE IF NOT EXISTS operaciones.rutas( id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES plataforma.tenants(id),empresa_id uuid NOT NULL,nodo_id uuid NOT NULL,repartidor_id uuid,fecha date NOT NULL,estado text NOT NULL DEFAULT 'PLANNED' CHECK(estado IN('PLANNED','ASSIGNED','IN_ROUTE','COMPLETED','CANCELLED')),ventana_ref text,creado_por uuid NOT NULL REFERENCES plataforma.users(id),creado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),actualizado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),version bigint NOT NULL DEFAULT 1,UNIQUE(tenant_id,empresa_id,id),FOREIGN KEY(tenant_id,empresa_id,nodo_id) REFERENCES operaciones.nodos(tenant_id,empresa_id,id),FOREIGN KEY(tenant_id,repartidor_id) REFERENCES transporte.repartidores(tenant_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS rutas_repartidor_activa_uidx ON operaciones.rutas(tenant_id,repartidor_id) WHERE estado IN('ASSIGNED','IN_ROUTE');
CREATE TABLE IF NOT EXISTS operaciones.ruta_paradas(tenant_id uuid NOT NULL,empresa_id uuid NOT NULL,ruta_id uuid NOT NULL,pedido_id uuid NOT NULL,secuencia integer NOT NULL CHECK(secuencia>0),estado text NOT NULL DEFAULT 'PENDING' CHECK(estado IN('PENDING','DELIVERED','FAILED')),evidencia jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(evidencia)='object'),actualizado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,empresa_id,ruta_id,pedido_id),UNIQUE(tenant_id,empresa_id,ruta_id,secuencia),FOREIGN KEY(tenant_id,empresa_id,ruta_id) REFERENCES operaciones.rutas(tenant_id,empresa_id,id),FOREIGN KEY(tenant_id,empresa_id,pedido_id) REFERENCES operaciones.pedidos(tenant_id,empresa_id,id));
CREATE TABLE IF NOT EXISTS operaciones.ruta_incidencias(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,empresa_id uuid NOT NULL,ruta_id uuid NOT NULL,tipo text NOT NULL,mensaje text NOT NULL CHECK(length(btrim(mensaje))BETWEEN 1 AND 1000),estado text NOT NULL DEFAULT 'OPEN' CHECK(estado IN('OPEN','RESOLVED')),creado_por uuid NOT NULL REFERENCES plataforma.users(id),creado_en timestamptz NOT NULL DEFAULT transaction_timestamp(),resuelto_en timestamptz,FOREIGN KEY(tenant_id,empresa_id,ruta_id) REFERENCES operaciones.rutas(tenant_id,empresa_id,id));
ALTER TABLE operaciones.rutas ENABLE ROW LEVEL SECURITY;ALTER TABLE operaciones.ruta_paradas ENABLE ROW LEVEL SECURITY;ALTER TABLE operaciones.ruta_incidencias ENABLE ROW LEVEL SECURITY;REVOKE ALL ON operaciones.rutas,operaciones.ruta_paradas,operaciones.ruta_incidencias FROM PUBLIC,mastererp_app;
INSERT INTO plataforma.permissions(code,description)VALUES('operations.routes.read','Read routes'),('operations.routes.write','Plan and execute routes')ON CONFLICT(code)DO NOTHING;
CREATE OR REPLACE FUNCTION operaciones.rutas_leer(p_empresa uuid,p_id uuid DEFAULT NULL,p_estado text DEFAULT NULL,p_limit integer DEFAULT 50)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,pg_temp AS $$DECLARE result jsonb;BEGIN IF p_limit NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.routes.read',p_empresa)IS NOT TRUE THEN RAISE EXCEPTION 'Route access denied' USING ERRCODE='42501';END IF;SELECT COALESCE(jsonb_agg(item ORDER BY fecha,id),'[]')INTO result FROM(SELECT r.fecha,r.id,jsonb_build_object('id',r.id,'node_id',r.nodo_id,'driver_id',r.repartidor_id,'date',r.fecha,'status',r.estado,'delivery_window_ref',r.ventana_ref,'version',r.version,'stops',(SELECT COALESCE(jsonb_agg(jsonb_build_object('order_id',s.pedido_id,'sequence',s.secuencia,'status',s.estado,'evidence',s.evidencia)ORDER BY s.secuencia),'[]')FROM operaciones.ruta_paradas s WHERE(s.tenant_id,s.empresa_id,s.ruta_id)=(r.tenant_id,r.empresa_id,r.id)))item FROM operaciones.rutas r WHERE r.tenant_id=plataforma.current_app_tenant_id()AND r.empresa_id=p_empresa AND(p_id IS NULL OR r.id=p_id)AND(p_estado IS NULL OR r.estado=p_estado)LIMIT p_limit)q;IF p_id IS NOT NULL AND jsonb_array_length(result)=0 THEN RAISE EXCEPTION 'Route not found' USING ERRCODE='P0002';END IF;RETURN CASE WHEN p_id IS NULL THEN result ELSE result->0 END;END $$;
CREATE OR REPLACE FUNCTION operaciones.ruta_crear(p_empresa uuid,p_nodo uuid,p_fecha date,p_ventana text,p_pedidos jsonb,p_key varchar)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,auditoria,pg_temp AS $$DECLARE tenant uuid:=plataforma.current_app_tenant_id();actor uuid:=plataforma.current_app_user_id();rid uuid:=gen_random_uuid();op text:='operations.routes.create';corr uuid;fp text;cached plataforma.idempotency_keys%ROWTYPE;response jsonb;line record;BEGIN IF jsonb_typeof(p_pedidos)<>'array'OR jsonb_array_length(p_pedidos)=0 OR length(p_key)NOT BETWEEN 1 AND 128 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.routes.write',p_empresa,p_nodo)IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'')IS DISTINCT FROM op THEN RAISE EXCEPTION 'Route creation denied' USING ERRCODE='42501';END IF;corr:=NULLIF(current_setting('app.correlation_id',true),'')::uuid;fp:=encode(public.digest(jsonb_build_array(p_empresa,p_nodo,p_fecha,p_ventana,p_pedidos)::text,'sha256'),'hex');PERFORM pg_advisory_xact_lock(hashtextextended(p_key,0));SELECT * INTO cached FROM plataforma.idempotency_keys WHERE idempotency_key=p_key;IF FOUND THEN IF cached.actor_user_id<>actor OR cached.request_tenant_id<>tenant OR cached.operation<>op OR cached.request_fingerprint<>fp THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='23505';END IF;RETURN cached.response_payload;END IF;INSERT INTO operaciones.rutas(id,tenant_id,empresa_id,nodo_id,fecha,ventana_ref,creado_por)VALUES(rid,tenant,p_empresa,p_nodo,p_fecha,NULLIF(btrim(p_ventana),''),actor);FOR line IN SELECT value::uuid pedido_id,ordinality seq FROM jsonb_array_elements_text(p_pedidos)WITH ORDINALITY LOOP IF NOT EXISTS(SELECT 1 FROM operaciones.pedidos WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=line.pedido_id AND estado='READY'AND ruta_ref IS NULL)THEN RAISE EXCEPTION 'Order not route-ready' USING ERRCODE='23514';END IF;INSERT INTO operaciones.ruta_paradas VALUES(tenant,p_empresa,rid,line.pedido_id,line.seq,'PENDING','{}',transaction_timestamp());UPDATE operaciones.pedidos SET ruta_ref=rid::text,version=version+1,actualizado_en=transaction_timestamp()WHERE id=line.pedido_id;END LOOP;response:=operaciones.rutas_leer(p_empresa,rid);INSERT INTO plataforma.idempotency_keys(idempotency_key,actor_user_id,operation,resource_id,request_fingerprint,request_tenant_id,response_payload)VALUES(p_key,actor,op,rid,fp,tenant,response);RETURN response;END $$;
CREATE OR REPLACE FUNCTION operaciones.ruta_asignar(p_empresa uuid,p_id uuid,p_version bigint,p_repartidor uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,transporte,plataforma,pg_temp AS $$DECLARE tenant uuid:=plataforma.current_app_tenant_id();r operaciones.rutas%ROWTYPE;BEGIN SELECT * INTO r FROM operaciones.rutas WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Route not found' USING ERRCODE='P0002';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.routes.write',p_empresa,r.nodo_id)IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'')IS DISTINCT FROM 'operations.routes.assign' THEN RAISE EXCEPTION 'Route assignment denied' USING ERRCODE='42501';END IF;IF r.version<>p_version THEN RAISE EXCEPTION 'Stale route version' USING ERRCODE='40001';END IF;IF r.estado<>'PLANNED'OR NOT EXISTS(SELECT 1 FROM transporte.repartidores d JOIN transporte.repartidor_nodos n ON n.tenant_id=d.tenant_id AND n.repartidor_id=d.id WHERE d.tenant_id=tenant AND d.id=p_repartidor AND d.estado='ACTIVE'AND d.disponibilidad='AVAILABLE'AND n.empresa_id=p_empresa AND n.nodo_id=r.nodo_id AND n.activo)THEN RAISE EXCEPTION 'Driver unavailable' USING ERRCODE='23514';END IF;UPDATE operaciones.rutas SET repartidor_id=p_repartidor,estado='ASSIGNED',version=version+1,actualizado_en=transaction_timestamp()WHERE id=p_id;RETURN operaciones.rutas_leer(p_empresa,p_id);END $$;
CREATE OR REPLACE FUNCTION operaciones.ruta_transicionar(p_empresa uuid,p_id uuid,p_version bigint,p_estado text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,transporte,plataforma,pg_temp AS $$DECLARE tenant uuid:=plataforma.current_app_tenant_id();r operaciones.rutas%ROWTYPE;BEGIN SELECT * INTO r FROM operaciones.rutas WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Route not found' USING ERRCODE='P0002';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.routes.write',p_empresa,r.nodo_id)IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'')IS DISTINCT FROM 'operations.routes.transition' THEN RAISE EXCEPTION 'Route transition denied' USING ERRCODE='42501';END IF;IF r.version<>p_version THEN RAISE EXCEPTION 'Stale route version' USING ERRCODE='40001';END IF;IF(r.estado,p_estado)NOT IN(('ASSIGNED','IN_ROUTE'),('IN_ROUTE','COMPLETED'),('PLANNED','CANCELLED'),('ASSIGNED','CANCELLED'))THEN RAISE EXCEPTION 'Invalid route transition' USING ERRCODE='23514';END IF;IF p_estado='COMPLETED'AND EXISTS(SELECT 1 FROM operaciones.ruta_paradas WHERE tenant_id=tenant AND empresa_id=p_empresa AND ruta_id=p_id AND estado='PENDING')THEN RAISE EXCEPTION 'Stops pending' USING ERRCODE='23514';END IF;UPDATE operaciones.rutas SET estado=p_estado,version=version+1,actualizado_en=transaction_timestamp()WHERE id=p_id;IF p_estado='IN_ROUTE'THEN UPDATE transporte.repartidores SET disponibilidad='ON_ROUTE',version=version+1 WHERE tenant_id=tenant AND id=r.repartidor_id;UPDATE operaciones.pedidos p SET estado='OUT_FOR_DELIVERY',version=version+1,actualizado_en=transaction_timestamp()FROM operaciones.ruta_paradas s WHERE s.ruta_id=p_id AND p.id=s.pedido_id;ELSIF p_estado IN('COMPLETED','CANCELLED')AND r.repartidor_id IS NOT NULL THEN UPDATE transporte.repartidores SET disponibilidad='AVAILABLE',version=version+1 WHERE tenant_id=tenant AND id=r.repartidor_id;END IF;RETURN operaciones.rutas_leer(p_empresa,p_id);END $$;
CREATE OR REPLACE FUNCTION operaciones.ruta_parada_finalizar(p_empresa uuid,p_ruta uuid,p_pedido uuid,p_estado text,p_evidencia jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operaciones,plataforma,pg_temp AS $$DECLARE tenant uuid:=plataforma.current_app_tenant_id();r operaciones.rutas%ROWTYPE;BEGIN SELECT * INTO r FROM operaciones.rutas WHERE tenant_id=tenant AND empresa_id=p_empresa AND id=p_ruta FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Route not found' USING ERRCODE='P0002';END IF;IF plataforma.has_current_tenant_capability('erp.operations','operations.routes.write',p_empresa,r.nodo_id)IS NOT TRUE OR NULLIF(current_setting('app.current_operation',true),'')IS DISTINCT FROM 'operations.routes.stop.complete' THEN RAISE EXCEPTION 'Stop completion denied' USING ERRCODE='42501';END IF;IF r.estado<>'IN_ROUTE'OR p_estado NOT IN('DELIVERED','FAILED')OR jsonb_typeof(p_evidencia)<>'object'THEN RAISE EXCEPTION 'Invalid stop state' USING ERRCODE='23514';END IF;UPDATE operaciones.ruta_paradas SET estado=p_estado,evidencia=p_evidencia,actualizado_en=transaction_timestamp()WHERE tenant_id=tenant AND empresa_id=p_empresa AND ruta_id=p_ruta AND pedido_id=p_pedido AND estado='PENDING';IF NOT FOUND THEN RAISE EXCEPTION 'Stop not found' USING ERRCODE='P0002';END IF;IF p_estado='DELIVERED'THEN UPDATE operaciones.pedidos SET estado='DELIVERED',version=version+1,actualizado_en=transaction_timestamp()WHERE id=p_pedido AND estado='OUT_FOR_DELIVERY';END IF;RETURN operaciones.rutas_leer(p_empresa,p_ruta);END $$;
REVOKE ALL ON FUNCTION operaciones.rutas_leer(uuid,uuid,text,integer),operaciones.ruta_crear(uuid,uuid,date,text,jsonb,varchar),operaciones.ruta_asignar(uuid,uuid,bigint,uuid),operaciones.ruta_transicionar(uuid,uuid,bigint,text),operaciones.ruta_parada_finalizar(uuid,uuid,uuid,text,jsonb)FROM PUBLIC;GRANT EXECUTE ON FUNCTION operaciones.rutas_leer(uuid,uuid,text,integer),operaciones.ruta_crear(uuid,uuid,date,text,jsonb,varchar),operaciones.ruta_asignar(uuid,uuid,bigint,uuid),operaciones.ruta_transicionar(uuid,uuid,bigint,text),operaciones.ruta_parada_finalizar(uuid,uuid,uuid,text,jsonb)TO mastererp_app;
